CREATE TABLE departments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE app_users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(180) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(24) NOT NULL, department_id BIGINT NOT NULL REFERENCES departments(id), active BOOLEAN NOT NULL DEFAULT TRUE, must_change_password BOOLEAN NOT NULL DEFAULT FALSE, auth_version INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE categories (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, description VARCHAR(200), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE tickets (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, title VARCHAR(180) NOT NULL, description TEXT NOT NULL, requester_id BIGINT NOT NULL REFERENCES app_users(id), department_id BIGINT NOT NULL REFERENCES departments(id), category_id BIGINT NOT NULL REFERENCES categories(id), assignee_id BIGINT REFERENCES app_users(id), status VARCHAR(30) NOT NULL, priority VARCHAR(16) NOT NULL, location VARCHAR(120), equipment VARCHAR(120), contact VARCHAR(80), solution TEXT, rating INTEGER CHECK(rating BETWEEN 1 AND 5), created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, sla_started_at TIMESTAMP WITH TIME ZONE NOT NULL,
 due_at TIMESTAMP WITH TIME ZONE NOT NULL, first_response_at TIMESTAMP WITH TIME ZONE, resolved_at TIMESTAMP WITH TIME ZONE, closed_at TIMESTAMP WITH TIME ZONE);
CREATE INDEX idx_ticket_requester ON tickets(requester_id);
CREATE INDEX idx_ticket_status_date ON tickets(status,created_at);
CREATE INDEX idx_ticket_assignee ON tickets(assignee_id);
CREATE INDEX idx_ticket_department ON tickets(department_id);
CREATE TABLE comments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ticket_id BIGINT NOT NULL REFERENCES tickets(id), author_id BIGINT NOT NULL REFERENCES app_users(id), body TEXT NOT NULL, internal BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX idx_comment_ticket ON comments(ticket_id,created_at);
CREATE TABLE ticket_history (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ticket_id BIGINT NOT NULL REFERENCES tickets(id), actor_id BIGINT NOT NULL REFERENCES app_users(id), action VARCHAR(100) NOT NULL, details VARCHAR(1000), created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX idx_history_ticket ON ticket_history(ticket_id,created_at);
CREATE TABLE attachments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ticket_id BIGINT NOT NULL REFERENCES tickets(id), author_id BIGINT NOT NULL REFERENCES app_users(id), original_name VARCHAR(180) NOT NULL, storage_key VARCHAR(80) NOT NULL UNIQUE, mime VARCHAR(80) NOT NULL, size BIGINT NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE notifications (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, recipient_id BIGINT NOT NULL REFERENCES app_users(id), ticket_id BIGINT REFERENCES tickets(id), title VARCHAR(220) NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX idx_notification_user ON notifications(recipient_id,is_read,created_at);
CREATE TABLE articles (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title VARCHAR(180) NOT NULL, excerpt VARCHAR(300) NOT NULL, body TEXT NOT NULL, category VARCHAR(80) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE triages (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, owner_id BIGINT NOT NULL REFERENCES app_users(id), category VARCHAR(40) NOT NULL, node VARCHAR(40) NOT NULL, result VARCHAR(30) NOT NULL, transcript TEXT NOT NULL, ticket_id BIGINT UNIQUE REFERENCES tickets(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL, finished_at TIMESTAMP WITH TIME ZONE);
